package deposit.common;

import static org.junit.jupiter.api.Assertions.*;
import java.util.*;
import org.junit.jupiter.api.Test;

/** Fixed scientific fixtures; expected values do not use planner/codec output. */
class HistoryPlannerTest {
    private Map<String,Object> image(String id,String kind,Object... fields){var m=Json.map("id",id,"kind",kind,"namespaceId","ns");m.putAll(Json.map(fields));return m;}
    private Map<String,Map<String,Object>> fixture(){var s=new TreeMap<String,Map<String,Object>>();s.put(HistoryCodec.key("Namespace","ns"),image("ns","Namespace","name","Fixture","description",""));s.put(HistoryCodec.key("Class","c"),image("c","Class","name","Specimen","comment",""));s.put(HistoryCodec.key("Object","o"),image("o","Object","position",List.of(0.0,0.0)));s.put(HistoryCodec.key("Membership","m"),image("m","Membership","objectId","o","classId","c"));s.put(HistoryCodec.key("ClassDescriptor","decl"),image("decl","ClassDescriptor","classId","c","name","Mass","type","Integer"));s.put(HistoryCodec.key("Descriptor","d"),image("d","Descriptor","objectId","o","name","Mass","value",20L));return s;}
    private Revision revision(String id,long seq,String kind,String reverse,Map<String,Map<String,Object>> before,Map<String,Map<String,Object>> after,Map<String,Set<String>> touches){var data=Json.map("kind",kind,"actorId","actor");if(reverse!=null)data.put(kind.equals("redo")?"reappliesRevisionId":"reversesRevisionId",reverse);return new Revision(id,seq,data,before,after,touches,Set.of());}
    private Revision mass(String id,long seq,long before,long after){return revision(id,seq,"edit",null,Map.of(HistoryCodec.key("Descriptor","d"),image("d","Descriptor","objectId","o","name","Mass","value",before)),Map.of(HistoryCodec.key("Descriptor","d"),image("d","Descriptor","objectId","o","name","Mass","value",after)),Map.of(HistoryCodec.key("Descriptor","d"),Set.of("value")));}
    @Test void journalRetainsIntermediateReturnTouches(){var s=fixture();var j=new ChangeSet(s);s.get(HistoryCodec.key("Descriptor","d")).put("value",30L);j.checkpoint(s);s.get(HistoryCodec.key("Descriptor","d")).put("value",20L);j.checkpoint(s);assertEquals(Set.of("value"),j.touches.get(HistoryCodec.key("Descriptor","d")));assertEquals(20L,j.before.get(HistoryCodec.key("Descriptor","d")).get("value"));assertEquals(20L,j.after.get(HistoryCodec.key("Descriptor","d")).get("value"));}
    @Test void journalRetainsCreationThenDeletionIdentity(){var s=fixture();var j=new ChangeSet(s);s.put(HistoryCodec.key("UserTool","tool"),image("tool","UserTool","name","Tool","data","  {not json}\n"));j.checkpoint(s);s.remove(HistoryCodec.key("UserTool","tool"));j.checkpoint(s);assertEquals(Set.of("*"),j.touches.get(HistoryCodec.key("UserTool","tool")));assertFalse(j.before.containsKey(HistoryCodec.key("UserTool","tool")));assertFalse(j.after.containsKey(HistoryCodec.key("UserTool","tool")));}
    @Test void auditOnlyChangesDoNotTouchOrRestore(){var s=fixture();var j=new ChangeSet(s);s.get(HistoryCodec.key("Descriptor","d")).put("updatedAt","2026-10-09T12:00Z");s.get(HistoryCodec.key("Descriptor","d")).put("updatedBy","other");j.checkpoint(s);assertTrue(j.touches.isEmpty());assertEquals(0,HistoryPlanner.restore(7,j.before,s,"baseline").plan().changes().touches.size());}
    @Test void reconstructsUnchangedBaselineMembershipAndConvertedDeclaration(){var base=fixture();var baseline=revision("base",0,"baseline",null,Map.of(),base,Map.of());var converted=Json.map("id","decl","kind","ClassDescriptor","namespaceId","ns","classId","c","name","Mass","type","Float");var value=image("d","Descriptor","objectId","o","name","Mass","value",20.0);var edit=revision("convert",1,"edit",null,Map.of(HistoryCodec.key("ClassDescriptor","decl"),base.get(HistoryCodec.key("ClassDescriptor","decl")),HistoryCodec.key("Descriptor","d"),base.get(HistoryCodec.key("Descriptor","d"))),Map.of(HistoryCodec.key("ClassDescriptor","decl"),converted,HistoryCodec.key("Descriptor","d"),value),Map.of(HistoryCodec.key("ClassDescriptor","decl"),Set.of("*"),HistoryCodec.key("Descriptor","d"),Set.of("value")));var history=List.of(baseline,edit);assertEquals("Integer",HistoryCodec.descriptorType(HistoryPlanner.reconstruct(history,"base"),base.get(HistoryCodec.key("Descriptor","d"))));var state=HistoryPlanner.reconstruct(history,"convert");assertEquals("Float",HistoryCodec.descriptorType(state,state.get(HistoryCodec.key("Descriptor","d"))));assertEquals(20.0,state.get(HistoryCodec.key("Descriptor","d")).get("value"));assertFalse(state.get(HistoryCodec.key("Descriptor","d")).containsKey("type"));}
    @Test void missingHistoricalDeclarationIsRejected(){var s=fixture();s.remove(HistoryCodec.key("ClassDescriptor","decl"));assertThrows(ExceptionHandler.DepositException.class,()->HistoryCodec.validate(s));}
    @Test void historicalPatternUsesLookupSchemaAndKeepsHistoryErrorTranslation(){
        var state=fixture();var definition=Json.map("objects",Json.map("root",Json.map("className","Specimen","root",true,"descriptors",List.of(Json.map("name","Mass")))));
        state.put(HistoryCodec.key("Pattern","p"),image("p","Pattern","name","ByMass","comment","","definition",definition));
        assertDoesNotThrow(()->HistoryCodec.validate(state));
        var missingClass=HistoryCodec.copy(state);var missingClassPattern=missingClass.get(HistoryCodec.key("Pattern","p"));var missingClassDefinition=ValueCodec.map(missingClassPattern.get("definition"));var missingClassRoles=ValueCodec.map(missingClassDefinition.get("objects"));ValueCodec.map(missingClassRoles.get("root")).put("className","Absent");
        var failure=assertThrows(ExceptionHandler.DepositException.class,()->HistoryCodec.validate(missingClass));
        assertTrue(failure.getMessage().contains("Invalid historical Pattern definition or compatibility"));
        var missingDeclaration=HistoryCodec.copy(state);var missingDeclarationPattern=missingDeclaration.get(HistoryCodec.key("Pattern","p"));var missingDeclarationDefinition=ValueCodec.map(missingDeclarationPattern.get("definition"));var missingDeclarationRoles=ValueCodec.map(missingDeclarationDefinition.get("objects"));ValueCodec.map(missingDeclarationRoles.get("root")).put("descriptors",List.of(Json.map("name","Absent")));
        assertThrows(ExceptionHandler.DepositException.class,()->HistoryCodec.validate(missingDeclaration));
        var proposedDeclaration=HistoryCodec.copy(state);var proposedPattern=proposedDeclaration.get(HistoryCodec.key("Pattern","p"));var proposedDefinition=ValueCodec.map(proposedPattern.get("definition"));var proposedRoles=ValueCodec.map(proposedDefinition.get("objects"));ValueCodec.map(proposedRoles.get("root")).put("descriptors",List.of(Json.map("name","Absent","type","String")));
        assertDoesNotThrow(()->HistoryCodec.validate(proposedDeclaration));
    }
    @Test void descriptorTypeTagAndWrongEndpointCategoryAreRejected(){var s=fixture();s.get(HistoryCodec.key("Descriptor","d")).put("type","Integer");assertThrows(ExceptionHandler.DepositException.class,()->HistoryCodec.validate(s));s.get(HistoryCodec.key("Descriptor","d")).remove("type");s.get(HistoryCodec.key("Membership","m")).put("classId","o");assertThrows(ExceptionHandler.DepositException.class,()->HistoryCodec.validate(s));}
    @Test void unrelatedFieldSurvivesSelectiveUndo(){var s=fixture();s.get(HistoryCodec.key("Object","o")).put("position",List.of(8.0,9.0));var a=mass("a",1,10,20);var plan=HistoryPlanner.inverse(2,s,a,List.of(a));assertTrue(plan.conflicts().isEmpty());assertEquals(10L,plan.result().get(HistoryCodec.key("Descriptor","d")).get("value"));assertEquals(List.of(8.0,9.0),plan.result().get(HistoryCodec.key("Object","o")).get("position"));
        for(String id:List.of("c","decl")){var before=new LinkedHashMap<>(s.get(id.equals("c")?HistoryCodec.key("Class","c"):HistoryCodec.key("ClassDescriptor","decl")));var after=new LinkedHashMap<>(before);after.put("comment","edited");assertEquals(Set.of("comment"),HistoryCodec.fields(before,after));after=new LinkedHashMap<>(before);after.put("order",9L);assertEquals(Set.of("order"),HistoryCodec.fields(before,after));after.put("name","Renamed");assertEquals(Set.of("*"),HistoryCodec.fields(before,after));}
    }
    @Test void sameValueReturnIndependentEditsConflict(){var a=mass("a",1,10,20);var b=mass("b",2,20,30);var d=mass("c",3,30,20);var plan=HistoryPlanner.inverse(3,fixture(),a,List.of(a,b,d));assertEquals(2,plan.conflicts().size());assertEquals("intervening-touch",plan.conflicts().getFirst().get("reason"));}
    @Test void emptyNetInterveningBatchConflicts(){var a=mass("a",1,10,20);var b=mass("batch",2,20,20);assertFalse(HistoryPlanner.inverse(2,fixture(),a,List.of(a,b)).conflicts().isEmpty());}
    @Test void undoneInterveningEditClearsConflict(){var a=mass("a",1,10,20);var b=mass("b",2,20,30);var u=revision("u",3,"undo","b",b.after(),b.before(),b.touches());assertTrue(HistoryPlanner.inverse(3,fixture(),a,List.of(a,b,u)).conflicts().isEmpty());}
    @Test void chainPreventsDuplicateReversalThroughOriginalAndRedoIds(){var a=mass("a",1,10,20);var u=revision("u",2,"undo","a",a.after(),a.before(),a.touches());var r=revision("r",3,"redo","u",a.before(),a.after(),a.touches());var list=List.of(a,u,r);assertFalse(HistoryPlanner.eligible(a,list,false));assertFalse(HistoryPlanner.eligible(u,list,true));assertTrue(HistoryPlanner.eligible(r,list,false));assertFalse(HistoryPlanner.eligible(u,list,false));}
    @Test void redoMayBeRepeatedOnlyAfterItsEffectIsUndone(){var a=mass("a",1,10,20);var u=revision("u",2,"undo","a",a.after(),a.before(),a.touches());var r=revision("r",3,"redo","u",a.before(),a.after(),a.touches());var uu=revision("uu",4,"undo","r",a.after(),a.before(),a.touches());assertTrue(HistoryPlanner.eligible(u,List.of(a,u,r,uu),true));assertFalse(HistoryPlanner.eligible(a,List.of(a,u,r,uu),false));}
    @Test void baselineAndUndoAreNeverUndoCandidates(){var b=revision("b",0,"baseline",null,Map.of(),fixture(),Map.of());assertFalse(HistoryPlanner.eligible(b,List.of(b),false));assertFalse(HistoryPlanner.eligible(b,List.of(b),true));}
    @Test void emptyNetActionRemainsEligibleWithEmptyInverse(){var a=mass("empty",1,20,20);assertTrue(HistoryPlanner.eligible(a,List.of(a),false));var plan=HistoryPlanner.inverse(1,fixture(),a,List.of(a));assertTrue(plan.conflicts().isEmpty());assertTrue(plan.changes().touches.isEmpty());assertEquals(20L,plan.result().get(HistoryCodec.key("Descriptor","d")).get("value"));}
    @Test void structuralDependencyRejectsDeletingClassWithLaterObject(){var s=fixture();var a=revision("class",1,"edit",null,Map.of(),Map.of(HistoryCodec.key("Class","c"),s.get(HistoryCodec.key("Class","c"))),Map.of(HistoryCodec.key("Class","c"),Set.of("*")));assertFalse(HistoryPlanner.inverse(3,s,a,List.of(a)).conflicts().isEmpty());}
    @Test void restorePreservesOpaqueToolAndNullValues(){var s=fixture();s.get(HistoryCodec.key("Descriptor","d")).put("value",null);s.put(HistoryCodec.key("UserTool","tool"),image("tool","UserTool","name","Tool","data"," \t非JSON {id:o}\n"));var plan=HistoryPlanner.restore(6,fixture(),s,"old");assertTrue(plan.plan().conflicts().isEmpty());assertNull(plan.plan().result().get(HistoryCodec.key("Descriptor","d")).get("value"));assertEquals(" \t非JSON {id:o}\n",plan.plan().result().get(HistoryCodec.key("UserTool","tool")).get("data"));assertEquals(1L,((Map<?,?>)plan.data().get("counts")).get("created"));assertEquals(1L,((Map<?,?>)plan.data().get("counts")).get("updated"));}
    @Test void inconsistentBeforeImageCannotRewriteHistoricalState(){var base=revision("base",0,"baseline",null,Map.of(),fixture(),Map.of());var changed=mass("bad",1,999,30);assertThrows(ExceptionHandler.DepositException.class,()->HistoryPlanner.reconstruct(List.of(base,changed),"bad"));}
    @Test void securityAndAggregatedFieldsAreNotCanonical(){var s=fixture();s.get(HistoryCodec.key("Object","o")).put("descriptors",Map.of("Mass",10L));assertThrows(ExceptionHandler.DepositException.class,()->HistoryCodec.validate(s));s.get(HistoryCodec.key("Object","o")).remove("descriptors");s.get(HistoryCodec.key("Namespace","ns")).put("roles",List.of("owner"));assertThrows(ExceptionHandler.DepositException.class,()->HistoryCodec.validate(s));}
    @Test void nullValueStillRetainsDeclarationDependencies(){var s=fixture();var journal=new ChangeSet(s);s.get(HistoryCodec.key("Descriptor","d")).put("value",null);journal.checkpoint(s);assertTrue(journal.dependencies.containsAll(List.of(HistoryCodec.key("Membership","m"),HistoryCodec.key("Class","c"),HistoryCodec.key("ClassDescriptor","decl"),HistoryCodec.key("Object","o"))));var selected=revision("a",1,"edit",null,Map.of(HistoryCodec.key("Descriptor","d"),journal.before.get(HistoryCodec.key("Descriptor","d"))),Map.of(HistoryCodec.key("Descriptor","d"),journal.after.get(HistoryCodec.key("Descriptor","d"))),journal.touches);selected=new Revision(selected.id(),selected.sequence(),selected.data(),selected.before(),selected.after(),selected.touches(),journal.dependencies);var later=revision("schema",2,"edit",null,Map.of(),Map.of(),Map.of(HistoryCodec.key("ClassDescriptor","decl"),Set.of("*")));assertFalse(HistoryPlanner.inverse(2,s,selected,List.of(selected,later)).conflicts().isEmpty());}
    @Test void patternHistoryRetainsDeclarationDependenciesAndRejectsIncompatibleRestore(){
        var state=fixture();var definition=Json.map("objects",Json.map("specimen",Json.map("className","Specimen","root",true,"descriptors",List.of(Json.map("name","Mass")))));
        String key=HistoryCodec.key("Pattern","pattern");state.put(key,image("pattern","Pattern","name","ByMass","comment","old","definition",definition));
        var journal=new ChangeSet(state);state.get(key).put("comment","new");journal.checkpoint(state);
        assertTrue(journal.dependencies.contains("ClassDescriptor\u0000decl"));
        assertTrue(HistoryCodec.schemaReferences(state,state.get("ClassDescriptor\u0000decl")).contains(key));
        var target=new Revision("pattern-edit",1,Json.map("kind","edit"),Map.of(key,journal.before.get(key)),Map.of(key,journal.after.get(key)),journal.touches,journal.dependencies);
        var later=revision("schema",2,"edit",null,Map.of(),Map.of(),Map.of("ClassDescriptor\u0000decl",Set.of("*")));
        assertFalse(HistoryPlanner.inverse(2,state,target,List.of(target,later)).conflicts().isEmpty());
        state.put("Pattern\u0000other",image("other","Pattern","name","Other","definition",Json.map("objects",Json.map("specimen",Json.map("className","Specimen","root",true,"descriptors",List.of())))));
        assertFalse(HistoryPlanner.restore(2,fixture(),state,"incompatible").plan().conflicts().isEmpty());
    }
}
